INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(26723, 0, 0, 'Preserve? Why? There\'s no truth in it. No no no... only in the taking! I see that now!', 14, 0, 100, 0, 0, 13450, 'keristrasza SAY_AGGRO'),
(26723, 1, 0, 'Now we\'ve come to the truth!', 14, 0, 100, 0, 0, 13453, 'keristrasza SAY_SLAY'),
(26723, 2, 0, 'Finish it! Finish it! Kill me, or I swear by the Dragonqueen you\'ll never see daylight again!', 14, 0, 100, 0, 0, 13452, 'keristrasza SAY_ENRAGE'),
(26723, 3, 0, 'Dragonqueen... Life-Binder... preserve... me.', 14, 0, 100, 0, 0, 13454, 'keristrasza SAY_DEATH'),
(26723, 4, 0, 'Stay. Enjoy your final moments.', 14, 0, 100, 0, 0, 13451, 'keristrasza SAY_CRYSTAL_NOVA'),
(26723, 5, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Keristrasza');
